import { handlerRegistry } from '../type-system/registry';
import { TypeValidationError } from '../type-system/errors';
import { Logger } from '../logger';

const logger = new Logger('IpcHandlers');

export type HandlerFunction<K extends IpcContractKey> = (
  data: z.infer<(typeof IpcContracts)[K]['request']>,
) => Promise<z.infer<(typeof IpcContracts)[K]['response']>>;

export class TypedIpcHandlers {
  /**
   * Register a type-safe handler
   */
  static register<K extends IpcContractKey>(channel: K, handler: HandlerFunction<K>): void {
    ipcMain.handle(channel, async (event, data) => {
      try {
        // Validate request
        const validation = validateIpcRequest(channel, data);
        if (!validation.success) {
          throw new TypeValidationError(channel, validation.errors || [], data);
        }

        // Call handler
        const response = await handler(validation.data!);

        // Validate response
        const responseValidation = validateIpcResponse(channel, response);
        if (!responseValidation.success) {
          logger.error(`Response validation failed for ${channel}`, {
            errors: responseValidation.errors,
          });
        }

        return { success: true, data: response };
      } catch (error) {
        logger.error(`Handler error for ${channel}`, error as Error);

        if (error instanceof TypeValidationError) {
          return {
            success: false,
            error: error.getAIDescription(),
            validationErrors: error.errors,
          };
        }

        return {
          success: false,
          error: error instanceof Error ? error.message : 'Unknown error',
        };
      }
    });

    handlerRegistry.register(channel);
  }

  /**
   * Batch register multiple handlers
   */
  static registerAll(
    handlers: Partial<{
      [K in IpcContractKey]: HandlerFunction<K>;
    }>,
  ): void {
    for (const [channel, handler] of Object.entries(handlers)) {
      if (handler) {
        this.register(channel as IpcContractKey, handler as any);
      }
    }
  }
}

